:root {
  --primary: #00ff88;
  --primary-dark: #00cc6e;
  --bg-dark: #0f172a;
  --card-dark: #1e293b;
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --border: #334155;
  --transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.light-theme {
  --bg-dark: #f8fafc;
  --card-dark: #ffffff;
  --text-main: #0f172a;
  --text-muted: #64748b;
  --border: #e2e8f0;
}

.dashboard-container {
  background-color: var(--bg-dark);
  color: var(--text-main);
  min-height: 100vh;
  transition: var(--transition);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 1.5rem;
  margin-bottom: 2rem;
}

.stat-card {
  background: var(--card-dark);
  padding: 1.5rem;
  border-radius: 1rem;
  border: 1px solid var(--border);
  transition: var(--transition);
  cursor: pointer;
  position: relative;
  overflow: hidden;
}

.stat-card:hover {
  transform: translateY(-5px) scale(1.02);
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.3);
  border-color: var(--primary);
}

.stat-icon {
  font-size: 2rem;
  color: var(--primary);
  margin-bottom: 1rem;
}

.charts-row {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 1.5rem;
  margin-bottom: 2rem;
}

@media (max-width: 1024px) {
  .charts-row {
    grid-template-columns: 1fr;
  }
}

.chart-container {
  background: var(--card-dark);
  padding: 1.5rem;
  border-radius: 1rem;
  border: 1px solid var(--border);
}

.data-table {
  width: 100%;
  border-collapse: collapse;
}

.data-table th {
  text-align: left;
  padding: 1rem;
  color: var(--text-muted);
  border-bottom: 1px solid var(--border);
}

.data-table td {
  padding: 1rem;
  border-bottom: 1px solid var(--border);
}

.badge-success {
  background: rgba(0, 255, 136, 0.1);
  color: var(--primary);
  padding: 0.25rem 0.75rem;
  border-radius: 100px;
  font-size: 0.85rem;
}

