const themeToggle = document.getElementById('theme-toggle');
const body = document.body;

themeToggle.addEventListener('click', () => {
  body.classList.toggle('light-theme');
  const icon = themeToggle.querySelector('i');
  if (body.classList.contains('light-theme')) {
    icon.className = 'bi bi-sun';
  } else {
    icon.className = 'bi bi-moon-stars';
  }
  localStorage.setItem('admin-theme', body.classList.contains('light-theme') ? 'light' : 'dark');
});

// Khởi tạo biểu đồ
function initCharts(revenueData, statusData) {
  const ctxRev = document.getElementById('revenue-chart').getContext('2d');
  new Chart(ctxRev, {
    type: 'line',
    data: {
      labels: revenueData.labels,
      datasets: [{
        label: 'Doanh thu (VNĐ)',
        data: revenueData.values,
        borderColor: '#00ff88',
        backgroundColor: 'rgba(0, 255, 136, 0.1)',
        fill: true,
        tension: 0.4
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: { legend: { display: false } },
      scales: { 
        y: { beginAtZero: true, grid: { color: 'rgba(255,255,255,0.05)' } },
        x: { grid: { display: false } }
      }
    }
  });

  const ctxStatus = document.getElementById('status-chart').getContext('2d');
  new Chart(ctxStatus, {
    type: 'doughnut',
    data: {
      labels: statusData.labels,
      datasets: [{
        data: statusData.values,
        backgroundColor: ['#00ff88', '#3b82f6', '#f59e0b', '#ef4444'],
        borderWidth: 0
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: { legend: { position: 'bottom' } }
    }
  });
}
